        List<Dictionary<string,object>> Profiles(string predicate,bool includeEndpoint){var list=new List<Dictionary<string,object>>();IntPtr s=IntPtr.Zero;try{string sql="SELECT a.id,a.username,COALESCE((SELECT d2.public_identity FROM presence p2 JOIN devices d2 ON d2.id=p2.device_id WHERE d2.account_id=a.id ORDER BY p2.seen_utc DESC LIMIT 1),(SELECT d3.public_identity FROM devices d3 WHERE d3.account_id=a.id ORDER BY d3.id LIMIT 1)),COALESCE((SELECT max(seen_utc) FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id),0),COALESCE((SELECT p.endpoint_host FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),''),COALESCE((SELECT p.endpoint_port FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),0),COALESCE((SELECT p.public_endpoint_host FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),''),COALESCE((SELECT p.public_endpoint_port FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),0),COALESCE((SELECT p.public_candidate_source FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),''),COALESCE((SELECT p.observed_classification FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),'') FROM accounts a WHERE "+predicate+" ORDER BY a.username";if(SqliteNative.prepare(database,sql,out s)!=0)return list;while(SqliteNative.step(s)==100){long seen=SqliteNative.columnLong(s,3);var profile=new Dictionary<string,object>{{"accountId",SqliteNative.columnLong(s,0)},{"username",SqliteNative.columnText(s,1)},{"publicIdentity",SqliteNative.columnText(s,2)},{"online",seen>=UnixNow()-90}};if(includeEndpoint){profile["endpointHost"]=SqliteNative.columnText(s,4)??"";profile["endpointPort"]=SqliteNative.columnLong(s,5);profile["publicEndp